package com.circle.oog;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

/** Explicitly limited static and single-direction sliding models; no shipment approval. */
@Service
public class EngineeringCalculationService {
    public static final String MODEL="OOG-STATIC2-DIRECT-SLIDING-1.0";
    public static final double GRAVITY=9.81;
    public record Support(Double xMm,Double areaMm2,Double allowablePressureMpa,Double capacityKn){}
    public record Lashing(String axis,Double horizontalAccelerationCoefficient,Double normalForceCoefficient,Double frictionCoefficient,Double effectiveCapacityKnPerLashing,Double verticalAngleDeg,Double planAngleDeg,Integer count,String evidence){}
    public record Input(UUID cargoId,String sourceMode,String inputEvidence,Double weightKg,Double cogXmm,Double cogYmm,Double cogZmm,Support supportA,Support supportB,Lashing lashing,String reason){}
    public record Decision(String decision,Long expectedVersion,String reason,String evidence){}
    private final JdbcTemplate jdbc;private final ObjectMapper json;
    public EngineeringCalculationService(JdbcTemplate jdbc,ObjectMapper json){this.jdbc=jdbc;this.json=json;}
    private Map<String,Object> plan(long tenant,UUID project,UUID plan){var rows=jdbc.queryForList("SELECT s.input_snapshot::text,s.result::text FROM oog_clp_scenario s JOIN oog_project p ON p.id=s.project_id WHERE p.tenant_id=? AND s.project_id=? AND s.id=?",tenant,project,plan);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"저장된 계획을 찾을 수 없습니다");return rows.getFirst();}
    @Transactional(rollbackFor=Exception.class) public Object create(long tenant,long actor,UUID project,UUID plan,Input request)throws Exception{
        if(request==null||request.cargoId()==null)throw bad("계획의 화물을 선택하세요");var source=plan(tenant,project,plan);var snapshot=json.readTree(source.get("input_snapshot").toString());JsonNode cargo=null;for(var c:snapshot.path("cargos"))if(c.path("id").asText().equals(request.cargoId().toString())){cargo=c;break;}if(cargo==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"저장 계획에 화물이 없습니다");
        var result=calculate(request,cargo);UUID id=UUID.randomUUID();var input=Map.of("request",request,"cargo",cargo,"planInput",snapshot,"savedPlan",json.readTree(source.get("result").toString()));
        jdbc.update("INSERT INTO oog_engineering_calculation(id,tenant_id,project_id,plan_id,author_id,input_snapshot,result) VALUES(?,?,?,?,?,cast(? as jsonb),cast(? as jsonb))",id,tenant,project,plan,actor,json.writeValueAsString(input),json.writeValueAsString(result));audit(tenant,actor,project,"ENGINEERING_CALCULATED",id);return Map.of("id",id,"result",result,"decisionVersion",0);
    }
    public Object list(long tenant,UUID project,UUID plan)throws Exception{plan(tenant,project,plan);var rows=jdbc.queryForList("SELECT id,author_id,input_snapshot::text,result::text,created_at FROM oog_engineering_calculation WHERE tenant_id=? AND project_id=? AND plan_id=? ORDER BY created_at DESC LIMIT 100",tenant,project,plan);for(var row:rows){row.put("input_snapshot",json.readTree(row.get("input_snapshot").toString()));row.put("result",json.readTree(row.get("result").toString()));var decisions=jdbc.queryForList("SELECT id,reviewer_id,version,decision,reason,evidence,created_at FROM oog_engineering_decision WHERE tenant_id=? AND calculation_id=? ORDER BY version DESC",tenant,row.get("id"));row.put("decisions",decisions);row.put("decisionVersion",decisions.isEmpty()?0:decisions.getFirst().get("version"));}return rows;}
    public Object context(long tenant,UUID project,UUID plan)throws Exception{return Map.of("cargos",json.readTree(this.plan(tenant,project,plan).get("input_snapshot").toString()).path("cargos"),"modelVersion",MODEL);}
    @Transactional(rollbackFor=Exception.class) public Object createExpanded(long tenant,long actor,UUID project,UUID plan,ExpandedEngineeringService.Input request)throws Exception{
        if(request==null||request.cargoId()==null)throw bad("저장 계획의 화물을 선택하세요");
        var source=plan(tenant,project,plan);var snapshot=json.readTree(source.get("input_snapshot").toString());JsonNode cargo=null;
        for(var item:snapshot.path("cargos"))if(item.path("id").asText().equals(request.cargoId().toString())){cargo=item;break;}
        if(cargo==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"저장 계획에 화물이 없습니다");
        var result=ExpandedEngineeringService.calculate(request,cargo);UUID record=UUID.randomUUID();
        var input=Map.of("request",request,"cargo",cargo,"planInput",snapshot,"savedPlan",json.readTree(source.get("result").toString()));
        jdbc.update("INSERT INTO oog_engineering_calculation(id,tenant_id,project_id,plan_id,author_id,input_snapshot,result) VALUES(?,?,?,?,?,cast(? as jsonb),cast(? as jsonb))",record,tenant,project,plan,actor,json.writeValueAsString(input),json.writeValueAsString(result));
        audit(tenant,actor,project,"EXPANDED_ENGINEERING_CALCULATED",record);return Map.of("id",record,"result",result,"decisionVersion",0);
    }
    @Transactional public Object decide(long tenant,long actor,UUID project,UUID plan,UUID calculation,Decision input)throws Exception{
        if(input==null||!Set.of("APPROVED_INTERNAL","REJECTED","REQUEST_REVIEW").contains(Objects.toString(input.decision(),""))||input.expectedVersion()==null||input.expectedVersion()<0)throw bad("검토 결정과 현재 버전을 확인하세요");text(input.reason(),"검토 근거");text(input.evidence(),"검토 자료 근거");
        var rows=jdbc.queryForList("SELECT author_id,result::text,input_snapshot::text FROM oog_engineering_calculation WHERE tenant_id=? AND project_id=? AND plan_id=? AND id=? FOR UPDATE",tenant,project,plan,calculation);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var row=rows.getFirst();long author=((Number)row.get("author_id")).longValue();var result=json.readTree(row.get("result").toString());validateDecision(author,actor,result,input.decision());
        if(input.decision().equals("APPROVED_INTERNAL")){var current=jdbc.queryForList("SELECT s.input_snapshot::text,s.result::text FROM oog_clp_scenario s JOIN oog_project p ON p.id=s.project_id WHERE p.tenant_id=? AND s.project_id=? AND s.id=? FOR SHARE OF s",tenant,project,plan);if(current.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND);var old=json.readTree(row.get("input_snapshot").toString());var now=current.getFirst();if(!old.path("planInput").equals(json.readTree(now.get("input_snapshot").toString()))||!old.path("savedPlan").equals(json.readTree(now.get("result").toString())))throw new ResponseStatusException(HttpStatus.CONFLICT,"저장 계획 snapshot이 계산 당시와 달라 새 계산이 필요합니다");}
        long version=jdbc.queryForObject("SELECT COALESCE(max(version),0) FROM oog_engineering_decision WHERE tenant_id=? AND calculation_id=?",Long.class,tenant,calculation);if(version!=input.expectedVersion())throw new ResponseStatusException(HttpStatus.CONFLICT,"다른 검토자가 결정을 기록했습니다");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO oog_engineering_decision(id,tenant_id,calculation_id,reviewer_id,version,decision,reason,evidence) VALUES(?,?,?,?,?,?,?,?)",id,tenant,calculation,actor,version+1,input.decision(),input.reason(),input.evidence());audit(tenant,actor,project,"ENGINEERING_DECISION_RECORDED",id);return Map.of("id",id,"decision",input.decision(),"version",version+1,"planStatus","PRE_PLAN","carrierApproved",false);
    }
    static void validateDecision(long author,long reviewer,JsonNode result,String decision){if(!decision.equals("APPROVED_INTERNAL"))return;if(author==reviewer)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"자신이 만든 계산 보고서는 스스로 승인할 수 없습니다");if(!result.path("eligibleForInternalApproval").asBoolean())throw new ResponseStatusException(HttpStatus.CONFLICT,"추정값·부족 입력·한도 초과가 있는 계산은 내부 승인할 수 없습니다");}
    private void audit(long tenant,long actor,UUID project,String action,UUID id){jdbc.update("INSERT INTO core_audit_history(project_id,tenant_id,actor_user_id,actor,action,detail) SELECT ?,?,?,username,?,jsonb_build_object('recordId',CAST(? AS text)) FROM core_user_account WHERE tenant_id=? AND user_id=?",project,tenant,actor,action,id.toString(),tenant,actor);}
    public static Map<String,Object> calculate(Input v,JsonNode cargo){
        if(v==null)throw bad("계산 입력이 필요합니다");if(!Set.of("CONFIRMED","ESTIMATED").contains(Objects.toString(v.sourceMode(),"")))throw bad("CoG와 입력의 확인/추정 구분이 필요합니다");text(v.reason(),"계산 근거");
        var missing=new ArrayList<String>();if(v.inputEvidence()==null||v.inputEvidence().isBlank())missing.add("INPUT_EVIDENCE");else text(v.inputEvidence(),"입력 확인 자료");
        number(v.weightKg(),0,1000000,false,"weightKg");number(v.cogXmm(),0,100000,true,"cogXmm");number(v.cogYmm(),0,30000,true,"cogYmm");number(v.cogZmm(),0,30000,true,"cogZmm");
        for(var entry:Map.of("weightKg",Optional.ofNullable(v.weightKg()),"cogXmm",Optional.ofNullable(v.cogXmm()),"cogYmm",Optional.ofNullable(v.cogYmm()),"cogZmm",Optional.ofNullable(v.cogZmm())).entrySet())if(entry.getValue().isEmpty())missing.add(entry.getKey());
        if(v.cogXmm()!=null&&v.cogXmm()>cargo.path("length").asDouble()||v.cogYmm()!=null&&v.cogYmm()>cargo.path("width").asDouble()||v.cogZmm()!=null&&v.cogZmm()>cargo.path("height").asDouble())throw bad("CoG는 저장된 포장 외형 범위 안의 기준점 좌표여야 합니다");
        var supports=new LinkedHashMap<String,Object>();boolean supportPass=false,lashingPass=false;
        for(var support:List.of(Optional.ofNullable(v.supportA()),Optional.ofNullable(v.supportB())))if(support.isPresent()){var s=support.get();number(s.xMm(),-100000,100000,true,"support.xMm");number(s.areaMm2(),0.000001,1000000000,true,"support.areaMm2");number(s.allowablePressureMpa(),0,100000,false,"support.allowablePressureMpa");number(s.capacityKn(),0,1000000,false,"support.capacityKn");}
        if(v.supportA()==null||v.supportB()==null||v.supportA().xMm()==null||v.supportB().xMm()==null||v.weightKg()==null||v.cogXmm()==null){supports.put("status","INCOMPLETE");missing.add("TWO_SUPPORT_GEOMETRY_AND_MASS");}
        else {
            double xa=v.supportA().xMm(),xb=v.supportB().xMm();if(xb-xa<0.001)throw bad("지지점 B와 A 사이의 X 거리는 0.001 mm 이상이어야 합니다");double weight=v.weightKg()*GRAVITY/1000,rb=weight*(v.cogXmm()-xa)/(xb-xa),ra=weight-rb;var a=supportResult("A",ra,v.supportA(),missing);var b=supportResult("B",rb,v.supportB(),missing);
            supportPass=Boolean.TRUE.equals(a.get("withinLimits"))&&Boolean.TRUE.equals(b.get("withinLimits"));supports.put("status",supportPass?"WITHIN_DECLARED_LIMITS":ra<0||rb<0?"UPLIFT_OR_UNSTABLE":!missing.stream().anyMatch(k->k.startsWith("SUPPORT_"))?"EXCEEDS_DECLARED_LIMITS":"INCOMPLETE");supports.put("weightKn",weight);supports.put("A",a);supports.put("B",b);supports.put("forceResidualKn",ra+rb-weight);supports.put("momentResidualKnMm",rb*(xb-xa)-weight*(v.cogXmm()-xa));supports.put("formula","RB=W*(xG-xA)/(xB-xA); RA=W-RB; pressureMPa=RkN*1000/areaMm2");
        }
        var lash=new LinkedHashMap<String,Object>();var l=v.lashing();
        if(l!=null){if(l.axis()!=null&&!Set.of("LONGITUDINAL","TRANSVERSE").contains(l.axis()))throw bad("라싱 검토 방향 오류");number(l.horizontalAccelerationCoefficient(),0,5,true,"horizontalAccelerationCoefficient");number(l.normalForceCoefficient(),0,2,true,"normalForceCoefficient");number(l.frictionCoefficient(),0,1,true,"frictionCoefficient");number(l.effectiveCapacityKnPerLashing(),0,1000000,false,"effectiveCapacityKnPerLashing");number(l.verticalAngleDeg(),0,90,true,"verticalAngleDeg");number(l.planAngleDeg(),0,90,true,"planAngleDeg");if(l.count()!=null&&(l.count()<1||l.count()>1000))throw bad("라싱 수량은 1~1000입니다");if(l.evidence()!=null&&!l.evidence().isBlank())text(l.evidence(),"라싱 계수와 유효 용량 근거");}
        if(l==null||v.weightKg()==null||l.axis()==null||l.horizontalAccelerationCoefficient()==null||l.normalForceCoefficient()==null||l.frictionCoefficient()==null||l.effectiveCapacityKnPerLashing()==null||l.verticalAngleDeg()==null||l.planAngleDeg()==null||l.count()==null||l.evidence()==null||l.evidence().isBlank()){lash.put("status","INCOMPLETE");missing.add("LASHING_DECLARED_COEFFICIENTS_CAPACITY_ANGLES_EVIDENCE");}
        else {double w=v.weightKg()*GRAVITY/1000,external=w*l.horizontalAccelerationCoefficient(),normal=w*l.normalForceCoefficient(),friction=normal*l.frictionCoefficient(),demand=Math.max(0,external-friction),projection=l.verticalAngleDeg()==90||l.planAngleDeg()==90?0:Math.cos(Math.toRadians(l.verticalAngleDeg()))*Math.cos(Math.toRadians(l.planAngleDeg())),resistance=l.count()*l.effectiveCapacityKnPerLashing()*projection;
            lashingPass=resistance>=demand;lash.put("status",lashingPass?"WITHIN_DECLARED_LIMITS":"INSUFFICIENT_DECLARED_CAPACITY");lash.put("axis",l.axis());lash.put("externalForceKn",external);lash.put("normalForceKn",normal);lash.put("frictionResistanceKn",friction);lash.put("requiredDirectResistanceKn",demand);lash.put("availableDirectResistanceKn",resistance);lash.put("marginKn",resistance-demand);lash.put("formula","F=mkg*9.81/1000*ch; N=mkg*9.81/1000*cn; D=max(0,F-mu*N); R=n*Ceff*cos(alpha)*cos(beta)");}
        double savedWeight=cargo.path("grossWeight").asDouble();boolean massMatches=v.weightKg()!=null&&savedWeight>0&&Math.abs(v.weightKg()-savedWeight)<=1e-6;
        boolean confirmed=v.sourceMode().equals("CONFIRMED"),eligible=confirmed&&missing.isEmpty()&&supportPass&&lashingPass&&massMatches;
        var result=new LinkedHashMap<String,Object>();result.put("modelVersion",MODEL);result.put("status",!missing.isEmpty()?"INCOMPLETE":!supportPass||!lashingPass?"FAILED_DECLARED_LIMITS":!massMatches?"MASS_MISMATCH_REQUIRES_NEW_PLAN":confirmed?"CALCULATED_REQUIRES_REVIEW":"ESTIMATED_REQUIRES_CONFIRMATION");result.put("sourceMode",v.sourceMode());result.put("missingInputs",missing);result.put("supports",supports);result.put("lashing",lash);result.put("eligibleForInternalApproval",eligible);result.put("approved",false);result.put("carrierApproved",false);result.put("planStatus","PRE_PLAN");result.put("gravityMs2",GRAVITY);
        result.put("assumptions",List.of("Single rigid cargo; gravity only for two static supports; no uplift restraint","Average compressive pressure over user declared effective contact area","Direct lashings oppose one declared horizontal direction, homogeneous and equal load sharing","Ceff supplied by reviewer includes weakest material, end fittings, cargo points, CTU points, derating and safety factors","No added friction credit from direct lashing vertical components; no walls/blocking credit"));
        result.put("savedGrossWeightKg",savedWeight);result.put("massMatchesSavedCargo",massMatches);result.put("warnings",massMatches?List.of("Declared evidence is not automatically authenticated; excluded physical checks and carrier approval remain required"):List.of("INPUT_MASS_DIFFERS_FROM_SAVED_CARGO: internal approval blocked; create a new plan with confirmed cargo mass","Declared evidence is not automatically authenticated; excluded physical checks and carrier approval remain required"));
        result.put("excludedChecks",List.of("OVERTURNING","DYNAMIC_SUPPORT_REACTIONS","STRUCTURAL_BENDING_AND_DEFLECTION","MULTI_SUPPORT_DISTRIBUTION","OTHER_DIRECTIONS_AND_TRANSPORT_LEGS","LASHING_PRETENSION_OR_TIE_DOWN","CARRIER_OR_CTU_CODE_COMPLIANCE"));result.put("sources",List.of("https://www.imo.org/en/ourwork/safety/pages/ctu-code.aspx","https://www.ilo.org/sites/default/files/wcmsp5/groups/public/@ed_dialogue/@sector/documents/publication/wcms_492710.pdf#page=114"));return result;
    }
    private static Map<String,Object> supportResult(String key,double reaction,Support s,List<String> missing){var r=new LinkedHashMap<String,Object>();r.put("reactionKn",reaction);r.put("pressureMpa",reaction<0||s.areaMm2()==null?null:reaction*1000/s.areaMm2());r.put("allowablePressureMpa",s.allowablePressureMpa());r.put("capacityKn",s.capacityKn());if(s.areaMm2()==null||s.allowablePressureMpa()==null||s.capacityKn()==null)missing.add("SUPPORT_"+key+"_AREA_AND_LIMITS");r.put("withinLimits",reaction>=0&&s.areaMm2()!=null&&s.allowablePressureMpa()!=null&&s.capacityKn()!=null&&reaction<=s.capacityKn()&&reaction*1000/s.areaMm2()<=s.allowablePressureMpa());return r;}
    static void number(Double value,double min,double max,boolean inclusiveMin,String name){if(value!=null&&(!Double.isFinite(value)||value<min||!inclusiveMin&&value==min||value>max))throw bad("수치 범위 오류: "+name);}
    static void text(String value,String label){if(value==null||value.isBlank()||value.length()>2000)throw bad(label+"를 입력하세요");}
    static ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.BAD_REQUEST,message);}
}

